{
  "script": "# squire_example.py — every function in the squire library, with usage shown.\n#\n# Press Run to execute this on the server. Only the read-only calls below actually run;\n# the write/delete examples are commented out so running this script never changes your\n# notes. Uncomment one to try it, or just read this as a reference and copy what you\n# need into your own script.\n#\n# A note is given by its name (\"Daily log\") or its path (\"Folder/Daily log.json\") — names\n# are unique, so either works for an existing note.\n\nimport squire\n\nprint(\"=== Reading things ===\")\n\n# Every note: [{\"path\", \"name\", \"modified\", \"size\"}, ...]\nall_notes = squire.notes()\nprint(f\"{len(all_notes)} notes in the notebook\")\n\n# Notes inside one folder, or whose name contains a word (both optional, combine freely)\n# squire.notes(folder=\"Projects\")\n# squire.notes(query=\"idea\")\n\n# The notebook's other files (images, PDFs, scripts) — just paths, not names\nscripts_and_images = squire.files()\nprint(f\"{len(scripts_and_images)} other files (images, PDFs, scripts)\")\n\n# Every folder's path\nprint(\"folders:\", squire.folders())\n\n# Does a note by this name/path exist?\nprint(\"'Daily log' exists:\", squire.exists(\"Daily log\"))\n\n# Search by name (every word in the query must match); content=True also searches inside\n# notes (slower, results get a \"snippet\"); limit caps how many come back (default 50)\n# results = squire.search(\"idea\", content=True, limit=20)\n\n# A whole note: {\"path\", \"name\", \"metadata\", \"blocks\", \"lastSaved\", ...}\nif all_notes:\n    first = all_notes[0][\"name\"]\n    note = squire.read(first)\n    print(f\"read {first!r}: {len(note.get('blocks') or [])} rows of blocks\")\n\n    # Every block as one flat list (hooked ones in order, then floating ones)\n    blocks = squire.blocks(first)\n    print(f\"{len(blocks)} blocks total\")\n\n    # All of a note's text, one block per line\n    print(\"first 80 chars:\", squire.text(first)[:80])\n\nprint(\"\\n=== Variables ===\")\n\n# A notebook-wide variable (leave `name` out) or a note's own variable (pass `name`).\n# get_variable raises SquireError if it doesn't exist, so check first or catch it.\ntry:\n    mood = squire.get_variable(\"Mood\")  # notebook-wide\n    print(\"Mood:\", mood)\nexcept squire.SquireError as err:\n    print(\"no notebook variable called Mood:\", err)\n\n# squire.get_variable(\"Score\", name=\"Daily log\")              # a note's own variable\n\n# type is \"text\", \"number\", \"boolean\", \"date\" (\"YYYY-MM-DD\") or \"time\" (\"HH:MM\");\n# value must match it. Creates the variable if it doesn't exist yet, otherwise changes it.\n# squire.set_variable(\"Mood\", \"text\", \"curious\")                        # notebook-wide\n# squire.set_variable(\"Score\", \"number\", 7, name=\"Daily log\")           # a note's variable\n# squire.delete_variable(\"Mood\")\n\nprint(\"\\n=== Writing things (commented out by default) ===\")\n\n# Make a new note: an error if the name is already taken. Each string in `paragraphs`\n# becomes its own text block. Returns the new note's path.\n# path = squire.create(\"Scratch/New idea\", paragraphs=[\"First thought\", \"Second thought\"])\n\n# Add one block to the end of an existing note. Returns the new block (with its id).\n# block = squire.append(\"Daily log\", \"Checked in at noon\")\n\n# Change a block you already have the id of: any of content, type, align, textColor,\n# background (get a block's id from squire.blocks() or squire.read()).\n# squire.set_block(\"Daily log\", block[\"id\"], content=\"Checked in at noon (edited)\")\n\n# Delete a block for good — it does NOT go to the trash, unlike deleting a note.\n# squire.delete_block(\"Daily log\", block[\"id\"])\n\n# Replace a whole note's metadata+blocks, creating it if it doesn't exist yet.\n# squire.write(\"Scratch/New idea\", {\"metadata\": {}, \"blocks\": [[{\"type\": \"text\", \"content\": \"Replaced\"}]]})\n\n# Move a note into a folder (\"\" moves it to the top level). Returns its new path.\n# squire.move(\"Scratch/New idea\", \"Projects\")\n\n# Make a folder (an error if it already exists).\n# squire.create_folder(\"Scratch\")\n\n# Delete a note — moves it to the notebook's trash, never destroys it.\n# squire.delete(\"Scratch/New idea\")\n\nprint(\"done\")\n"
}